package io.github.diodeme.ji.session;

import io.github.diodeme.ji.ai.Message;
import io.github.diodeme.ji.ai.ModelRef;
import io.github.diodeme.ji.ai.Usage;
import java.util.List;
import java.util.Optional;

/** Durable Agent Session projection used by Core and inbound adapters. */
public record SessionSnapshot(
        String sessionId,
        long revision,
        ModelRef model,
        String workingDirectory,
        List<Message> transcript,
        Usage usage,
        Optional<ActiveRun> activeRun) {
    public SessionSnapshot {
        if (sessionId == null || sessionId.isBlank()) throw new IllegalArgumentException("sessionId must not be blank");
        if (revision < 0) throw new IllegalArgumentException("revision must be non-negative");
        if (model == null) throw new IllegalArgumentException("model must not be null");
        if (workingDirectory == null || workingDirectory.isBlank()) throw new IllegalArgumentException("workingDirectory must not be blank");
        transcript = List.copyOf(transcript);
        if (usage == null) throw new IllegalArgumentException("usage must not be null");
        activeRun = activeRun == null ? Optional.empty() : activeRun;
    }

    public record ActiveRun(String runId, Status status, long revision) {
        public ActiveRun {
            if (runId == null || runId.isBlank()) throw new IllegalArgumentException("runId must not be blank");
            if (status == null || revision < 0) throw new IllegalArgumentException("active run state is invalid");
        }
    }

    public enum Status { RUNNING, CANCELLING, PAUSED }
}
